exec(json.loads("\"import sys,pathlib,json,base64,hashlib,termios,subprocess,shutil,os,datetime,zipfile,urllib.request\\nroot=pathlib.Path(os.environ.get(\\\"OPENFEMA_RECEIVING_ROOT\\\",\\\"/dev/openfema-native-3bda-20261012\\\"));root.mkdir(mode=0o700,exist_ok=True)\\nassert not root.is_symlink() and root.is_dir() and root.stat().st_uid==os.getuid() and root.stat().st_mode&0o077==0,\\\"Use an owned private receiving root\\\"\\nif sys.stdin.isatty():\\n a=termios.tcgetattr(0);a[3]&=~(termios.ICANON|termios.ECHO);a[6][termios.VMIN]=1;a[6][termios.VTIME]=0;termios.tcsetattr(0,termios.TCSANOW,a)\\nenv={**os.environ,\\\"PYTHONDONTWRITEBYTECODE\\\":\\\"1\\\",\\\"TMPDIR\\\":str(root)}\\ndep_candidates=[os.environ.get(\\\"OPENFEMA_NODE_MODULES\\\",\\\"\\\"),\\\"/workspace/scratch/2d589b11f06d/scf-oauth-deps/node_modules\\\",os.environ.get(\\\"CODEX_PRIMARY_RUNTIME_NODE_MODULES\\\",\\\"\\\")]\\ndeps=[p for p in dep_candidates if p and pathlib.Path(p).is_dir()]\\nif deps:\\n env[\\\"NODE_PATH\\\"]=os.pathsep.join(deps)\\n selected_deps=next((p for p in deps if pathlib.Path(p,\\\"re2js\\\").exists()),deps[0])\\n if not (root/\\\"node_modules\\\").exists():os.symlink(selected_deps,root/\\\"node_modules\\\",target_is_directory=True)\\nnode=os.environ.get(\\\"CODEX_PRIMARY_RUNTIME_NODE\\\") or shutil.which(\\\"node\\\")\\nlogs=root/\\\"native-logs\\\";logs.mkdir(mode=0o700,exist_ok=True)\\nphases=[]\\ndef saved():\\n result={\\\"schema\\\":\\\"stellar-forge.openfema-native-operation.v1\\\",\\\"operationId\\\":os.environ.get(\\\"OPENFEMA_OPERATION_ID\\\",\\\"SCF-OPENFEMA-PORTFOLIO-3BDA-20261012\\\"),\\\"root\\\":str(root),\\\"pid\\\":os.getpid(),\\\"node\\\":node,\\\"phases\\\":phases,\\\"updatedAt\\\":datetime.datetime.now(datetime.timezone.utc).isoformat()}\\n p=root/\\\"NATIVE_OPERATION.json\\\";p.write_text(json.dumps(result,indent=2)+\\\"\\\\n\\\");p.chmod(0o600);return result\\ndef selected(name):\\n p=root/name\\n assert not pathlib.PurePath(name).is_absolute() and p.is_relative_to(root) and \\\"..\\\" not in pathlib.PurePath(name).parts\\n return p\\ndef put(files):\\n out=[]\\n for f in files:\\n  p=selected(f[\\\"path\\\"]);b=base64.b64decode(f[\\\"base64\\\"],validate=True) if \\\"base64\\\" in f else f[\\\"text\\\"].encode(\\\"utf-8\\\")\\n  assert hashlib.sha256(b).hexdigest()==f[\\\"sha256\\\"],f[\\\"path\\\"]\\n  p.parent.mkdir(parents=True,exist_ok=True,mode=0o700)\\n  if p.exists():assert p.read_bytes()==b,f[\\\"path\\\"]\\n  else:\\n   with p.open(\\\"xb\\\") as h:h.write(b)\\n  p.chmod(0o600);out.append({\\\"path\\\":f[\\\"path\\\"],\\\"bytes\\\":len(b),\\\"sha256\\\":f[\\\"sha256\\\"]})\\n return {\\\"count\\\":len(out),\\\"bytes\\\":sum(f[\\\"bytes\\\"] for f in out)}\\ndef run(q):\\n label=q[\\\"label\\\"];assert label.replace(\\\"-\\\",\\\"\\\").replace(\\\"_\\\",\\\"\\\").isalnum()\\n argv=[node if a==\\\"@node\\\" else str(root/a[6:]) if a.startswith(\\\"@root/\\\") else a for a in q[\\\"argv\\\"]]\\n print(json.dumps({\\\"phase\\\":label,\\\"startedAt\\\":datetime.datetime.now(datetime.timezone.utc).isoformat()}),flush=True)\\n r=subprocess.run(argv,cwd=root,env=env,capture_output=True,text=True)\\n for name,text in [(label+\\\".stdout\\\",r.stdout),(label+\\\".stderr\\\",r.stderr)]:\\n  p=logs/name;p.write_text(text);p.chmod(0o600)\\n try:value=json.loads(r.stdout)\\n except:value={\\\"stdout\\\":r.stdout[-12000:]}\\n item={\\\"phase\\\":label,\\\"exitCode\\\":r.returncode,\\\"result\\\":value,\\\"stderr\\\":r.stderr[-5000:],\\\"completedAt\\\":datetime.datetime.now(datetime.timezone.utc).isoformat()}\\n phases.append(item);saved()\\n return item\\nprint(\\\"OPENFEMA_PERSISTENT_READY \\\"+json.dumps({\\\"root\\\":str(root),\\\"pid\\\":os.getpid(),\\\"node\\\":node,\\\"freeBytes\\\":shutil.disk_usage(\\\"/dev\\\").free,\\\"memoryCurrent\\\":pathlib.Path(\\\"/sys/fs/cgroup/memory.current\\\").read_text().strip() if pathlib.Path(\\\"/sys/fs/cgroup/memory.current\\\").exists() else None,\\\"memoryMax\\\":pathlib.Path(\\\"/sys/fs/cgroup/memory.max\\\").read_text().strip() if pathlib.Path(\\\"/sys/fs/cgroup/memory.max\\\").exists() else None,\\\"dependencyPaths\\\":deps,\\\"primaryNodeModules\\\":os.environ.get(\\\"CODEX_PRIMARY_RUNTIME_NODE_MODULES\\\"),\\\"chromium\\\":next((p for p in [os.environ.get(\\\"OPENFEMA_CHROMIUM\\\",\\\"\\\"),\\\"/workspace/scratch/7573d13065d5/aurora_ops/browser-runtime/tmp/chromium\\\",\\\"/workspace/scratch/bc0850d7ba23/browser-runtime/chrome-headless-shell\\\"] if p and pathlib.Path(p).is_file()),None)}),flush=True)\\nwhile True:\\n raw=sys.stdin.buffer.readline()\\n if not raw:break\\n try:\\n  q=json.loads(raw);cmd=q[\\\"command\\\"]\\n  if cmd==\\\"stop\\\":print(\\\"OPENFEMA_BRIDGE_STOPPED\\\",flush=True);break\\n  if cmd==\\\"put\\\":print(json.dumps({\\\"command\\\":\\\"put\\\",\\\"result\\\":put(q[\\\"files\\\"])}),flush=True)\\n  elif cmd==\\\"run\\\":print(json.dumps({\\\"command\\\":\\\"run\\\",\\\"result\\\":run(q)}),flush=True)\\n  elif cmd==\\\"upload\\\":\\n   p=selected(q[\\\"source\\\"]);b=p.read_bytes();digest=hashlib.sha256(b).hexdigest();assert digest==q[\\\"sha256\\\"]\\n   session=q[\\\"upload\\\"];assert session[\\\"method\\\"]==\\\"PUT\\\" and session[\\\"upload_url\\\"].startswith(\\\"https://\\\")\\n   request=urllib.request.Request(session[\\\"upload_url\\\"],data=b,method=session[\\\"method\\\"],headers=session[\\\"required_headers\\\"])\\n   with urllib.request.urlopen(request,timeout=45) as response:\\n    response_body=response.read();result={\\\"command\\\":\\\"upload\\\",\\\"path\\\":q[\\\"source\\\"],\\\"bytes\\\":len(b),\\\"sha256\\\":digest,\\\"status\\\":response.status,\\\"upload_session_id\\\":session[\\\"upload_session_id\\\"]}\\n   print(json.dumps(result),flush=True)\\n  elif cmd==\\\"pack\\\":\\n   target=selected(q[\\\"target\\\"]);source=selected(q[\\\"source\\\"]);entries=[]\\n   assert source.is_dir() and not source.is_symlink()\\n   with zipfile.ZipFile(target,\\\"w\\\",compression=zipfile.ZIP_DEFLATED,compresslevel=6) as archive:\\n    for p in sorted(source.rglob(\\\"*\\\")):\\n     if p.is_symlink():raise ValueError(\\\"Symbolic link in receiving archive: \\\"+str(p))\\n     if p.is_file():\\n      name=str(p.relative_to(source));archive.write(p,name);entries.append({\\\"path\\\":name,\\\"bytes\\\":p.stat().st_size})\\n   target.chmod(0o600);b=target.read_bytes()\\n   print(json.dumps({\\\"command\\\":\\\"pack\\\",\\\"path\\\":q[\\\"target\\\"],\\\"bytes\\\":len(b),\\\"sha256\\\":hashlib.sha256(b).hexdigest(),\\\"entries\\\":len(entries)}),flush=True)\\n  elif cmd==\\\"status\\\":print(json.dumps({\\\"command\\\":\\\"status\\\",\\\"result\\\":saved(),\\\"files\\\":[{\\\"path\\\":str(p.relative_to(root)),\\\"bytes\\\":p.stat().st_size} for p in root.rglob(\\\"*\\\") if p.is_file()]}),flush=True)\\n  elif cmd==\\\"read\\\":\\n   p=selected(q[\\\"path\\\"]);b=p.read_bytes();offset=int(q.get(\\\"offset\\\",0));length=min(int(q.get(\\\"length\\\",49152)),49152);assert offset>=0 and length>0\\n   print(json.dumps({\\\"path\\\":q[\\\"path\\\"],\\\"bytes\\\":len(b),\\\"sha256\\\":hashlib.sha256(b).hexdigest(),\\\"offset\\\":offset,\\\"base64\\\":base64.b64encode(b[offset:offset+length]).decode(),\\\"hasMore\\\":offset+length<len(b)}),flush=True)\\n  else:raise ValueError(\\\"Use put, run, read, status or stop\\\")\\n except Exception as e:print(json.dumps({\\\"error\\\":str(e)}),flush=True)\\n\""),{'__name__':'__main__'})
shared=pathlib.Path('/dev/shm/b710-stac-managed-applications-native-delivery');shared.mkdir(mode=0o700,parents=True,exist_ok=True)
selected=['NATIVE_OPERATION.json','transfer-'+attempt_label+'.json','delivery/one-allocation-result.json','delivery/native-continuation-exit.json','delivery/source-receiving.json','delivery/missing-objects.json','continuation.json','continuation-error.json','runtime-ready.json']
retained=[]
for name in selected:
 source=root/name
 if source.is_file():
  target=shared/(attempt_label+'-'+source.name)
  try:
   data=source.read_bytes()
   if target.exists():assert target.read_bytes()==data
   else:target.write_bytes(data)
   target.chmod(0o600);retained.append({'path':str(target),'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()})
  except Exception as e:print(json.dumps({'phase':'SHARED_RESULT_SAVE','file':name,'errorType':type(e).__name__,'errno':getattr(e,'errno',None)}),flush=True)
archive=root/'SCF_STAC_Managed_Applications_Native_20261012.zip'
if archive.is_file():
 target=shared/(attempt_label+'-'+archive.name);pending=target.with_suffix('.partial')
 if shutil.disk_usage(shared).free>=archive.stat().st_size+1024*1024:
  created=False
  try:
   with archive.open('rb') as stream:archive_digest=hashlib.file_digest(stream,'sha256').hexdigest()
   if target.exists():
    with target.open('rb') as stream:assert hashlib.file_digest(stream,'sha256').hexdigest()==archive_digest
   else:
    with pending.open('xb') as sink,archive.open('rb') as source:
     created=True
     shutil.copyfileobj(source,sink,1024*1024)
    with pending.open('rb') as stream:assert hashlib.file_digest(stream,'sha256').hexdigest()==archive_digest
    pending.chmod(0o600);pending.replace(target);created=False
   retained.append({'path':str(target),'bytes':target.stat().st_size,'sha256':archive_digest})
  except Exception as e:
   if created and pending.exists():pending.unlink()
   print(json.dumps({'phase':'SHARED_ARCHIVE_SAVE','errorType':type(e).__name__,'errno':getattr(e,'errno',None)}),flush=True)
 else:print(json.dumps({'phase':'SHARED_ARCHIVE_SPACE','bytes':archive.stat().st_size,'available':shutil.disk_usage(shared).free}),flush=True)
print(json.dumps({'phase':'ORIGINAL_NATIVE_OUTPUTS_RETAINED','files':retained}),flush=True)
